import { showModal } from '@ui-kit/Modal';

import ScheduleResultPreviewModal, { IScheduleResultPreviewModalProps } from './index';
interface IShowScheduleEditModalArgs extends IScheduleResultPreviewModalProps {
  title?: string;
}

export const showScheduleResultPreviewModal = ({
  scheduleItem,
  scheduleResult,
  title,
}: IShowScheduleEditModalArgs) => {
  showModal({
    title: title || scheduleResult.name || scheduleItem.name,
    children: (
      <ScheduleResultPreviewModal scheduleItem={scheduleItem} scheduleResult={scheduleResult} />
    ),
  });
};
