export enum HikingScheduleResultStatus {
  'completed' = 'completed',
  'failed' = 'failed',
  'skipped' = 'skipped',
  'rescheduled' = 'rescheduled',
  'swapped' = 'swapped',
}
export interface IHikingScheduleResultDTO {
  id: string;
  id_hiking_schedule: string;
  id_hiking_schedule_related: string | null;
  d1: string | null;
  d2: string | null;
  name: string;
  status: HikingScheduleResultStatus;
  text: string;

  created_at: string;
  updated_at: string | null;
  id_author: string;

  id_hiking: string;
  original_d1: string;
  original_d2: string;
  original_name: string;
  original_description: string;
}

export interface IHikingScheduleResultAddDTO {
  id_hiking_schedule: number;
  id_hiking_schedule_related: number | null;
  d1: string | null;
  d2: string | null;
  name: string;
  text: string;
  status: HikingScheduleResultStatus;
}

export interface IHikingScheduleResultUpdateDTO
  extends Omit<IHikingScheduleResultAddDTO, 'id_hiking_schedule'> {
  id: number;
}
